package com.lmspilot.identity.domain; import java.time.Instant; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; public interface UserAccountRepository extends JpaRepository<UserAccountEntity,UUID> { Optional<UserAccountEntity> findByUsernameIgnoreCase(String username); Optional<UserAccountEntity> findByCodeIgnoreCase(String code); boolean existsByUsernameIgnoreCase(String username); boolean existsByCodeIgnoreCase(String code); long countByStatusNot(AccountStatus status); @Query("select distinct u from UserAccountEntity u left join u.roles r where (cast(:query as string) is null or lower(u.username) like lower(concat('%',cast(:query as string),'%')) or lower(u.fullName) like lower(concat('%',cast(:query as string),'%')) or lower(u.code) like lower(concat('%',cast(:query as string),'%'))) and (:status is null or u.status=:status) and (cast(:role as string) is null or lower(r.code)=lower(cast(:role as string)))") Page<UserAccountEntity> search(@Param("query") String query,@Param("status") AccountStatus status,@Param("role") String role,Pageable pageable); }
